#include <iostream>
#include <vector>
#include <utility>

void enhancedBubbleSort(std::vector<int>& arr) {
    const size_t n = arr.size();
    for (size_t i = 0; i < n - 1; ++i) {
        bool swapped = false;
        for (size_t j = 0; j < n - 1 - i; ++j) {
            if (arr[j] > arr[j + 1]) {
                std::swap(arr[j], arr[j + 1]);
                swapped = true;
            }
        }
        if (!swapped) {
            break; // Array is sorted early
        }
    }
}

int main() {
    std::vector<int> data = {64, 34, 25, 12, 22, 11, 90};
    enhancedBubbleSort(data);
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << (i + 1 == data.size() ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

class BucketSort {
public:
    static void sort(std::vector<int>& arr) {
        if (arr.empty()) return;
        int maxVal = *std::max_element(arr.begin(), arr.end());

        for (int exp = 1; maxVal / exp > 0; exp *= 10) {
            // 10 buckets (0-9)
            std::vector<std::vector<int>> buckets(10);

            // Distribution pass
            for (int val : arr) {
                int digit = (val / exp) % 10;
                buckets[digit].push_back(val);
            }

            // Gathering pass
            size_t idx = 0;
            for (int b = 0; b < 10; ++b) {
                for (int val : buckets[b]) {
                    arr[idx++] = val;
                }
            }
        }
    }
};

int main() {
    std::vector<int> data = {97, 3, 100, 45, 12, 68};
    BucketSort::sort(data);
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << (i + 1 == data.size() ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

// Recursive Linear Search (Ex 20.8)
int recursiveLinearSearch(const std::vector<int>& arr, int key, size_t index) {
    if (index >= arr.size()) return -1;
    if (arr[index] == key) return static_cast<int>(index);
    return recursiveLinearSearch(arr, key, index + 1);
}

// Recursive Binary Search (Ex 20.9)
int recursiveBinarySearch(const std::vector<int>& arr, int key, int low, int high) {
    if (low > high) return -1;
    int mid = low + (high - low) / 2;
    if (arr[mid] == key) return mid;
    if (key < arr[mid]) return recursiveBinarySearch(arr, key, low, mid - 1);
    return recursiveBinarySearch(arr, key, mid + 1, high);
}

// Bidirectional Partitioning (Ex 20.10)
int partition(std::vector<int>& arr, int left, int right) {
    int pivotIndex = left;
    while (left < right) {
        while (left < right && arr[right] >= arr[pivotIndex]) {
            --right;
        }
        if (left < right) {
            std::swap(arr[pivotIndex], arr[right]);
            pivotIndex = right;
        }
        while (left < right && arr[left] <= arr[pivotIndex]) {
            ++left;
        }
        if (left < right) {
            std::swap(arr[pivotIndex], arr[left]);
            pivotIndex = left;
        }
    }
    return pivotIndex;
}

void quickSort(std::vector<int>& arr, int low, int high) {
    if (low < high) {
        int p = partition(arr, low, high);
        quickSort(arr, low, p - 1);
        quickSort(arr, p + 1, high);
    }
}

int main() {
    std::vector<int> data = {37, 2, 6, 4, 89, 8, 10, 12, 68, 45};
    quickSort(data, 0, static_cast<int>(data.size()) - 1);
    for (size_t i = 0; i < data.size(); ++i) {
        std::cout << data[i] << (i + 1 == data.size() ? "" : " ");
    }
    std::cout << "\n";
    std::cout << "Search 89: " << recursiveBinarySearch(data, 89, 0, static_cast<int>(data.size()) - 1) << "\n";
    return 0;
}
